TP.register({id:"lp1-g3",lp:1,grade:"3",mode:"baseline",nextGrade:"4th grade",build(E){const F=E.F;const BRO="Leo";const FABLE=`Nora had practiced her song for three weeks. Tonight was the school talent show, and she had butterflies in her stomach. She peeked around the curtain. Every seat in the gym was full. “I can’t do it,” she whispered to her brother, ${BRO}. “My legs feel like jelly.” ${BRO} smiled. “You sing that song in the shower every morning. This will be a piece of cake. Just look at me in the front row and pretend we are at home.” When Nora’s name was called, she walked to the middle of the stage. The lights were bright and hot. For a moment she froze. Then she spotted ${BRO} waving both arms like a windmill. The gym went quiet, so quiet that Nora could hear the hum of the lights over her head. She found ${BRO}’s face in the front row and kept her eyes there. Her hands were shaking, and she pressed them flat against her sides so nobody would see. The piano player gave her a nod and started the first notes twice, because the first time Nora missed her cue. Nora took a deep breath and began to sing. Her voice was quiet at first, but it grew stronger with every line. By the last verse, people were clapping along. When she finished, the whole gym cheered. Nora ran off the stage and hugged her brother. “You were right,” she said. “After the first line, it was a piece of cake!” “I told you,” said ${BRO}. “Now I’m starving. All that waving made me hungry enough to eat a horse.”`;const TEXT_A={title:"A Coat of Fur",body:"Sea otters live in the cold water of the Pacific Ocean. Most sea animals have a thick layer of fat to keep them warm. But sea otters do not. Instead, they have the thickest fur of any animal. An otter spends hours each day cleaning its fur. Clean fur traps tiny bubbles of air next to the skin, and the air keeps the cold water out."};const TEXT_B={title:"Always Eating",body:"A sea otter eats a lot. Every day it eats food that weighs about one fourth as much as its own body. Otters dive to the sea floor for crabs, clams, and sea urchins. Then they float on their backs and use a rock to crack the shells open. All that food gives an otter’s body energy. It needs that energy to stay warm in cold water."};const MOON="The moon does not make its own light. It shines because sunlight bounces off it. The moon travels around Earth about once a month. As it moves, we see different amounts of its sunny side. When we see the whole sunny side, we call it a full moon. When the sunny side faces away from us, the moon looks dark, and we call it a new moon. The moon is not really changing shape. We are just seeing it from a different angle.";const WORDS=["preview","dislike","careless","invention","celebration","comfortable","dangerous","remember","thought","enough","mistrandful","replomable"];function twoTextsHtml(){return`<div class="texts"><article><h3>Text 1: ${TEXT_A.title}</h3><p>${TEXT_A.body}</p></article><article><h3>Text 2: ${TEXT_B.title}</h3><p>${TEXT_B.body}</p></article></div>`}function fracRect(xs,shade){const w=320,h=130;let s=`<svg viewBox="0 0 ${w+8} ${h+8}" width="${w+8}" role="img" aria-label="Rectangle split into ${xs.length-1} parts">`;for(let k=0;k<xs.length-1;k++)s+=`<rect x="${4+xs[k]*w}" y="4" width="${(xs[k+1]-xs[k])*w}" height="${h}" fill="${k<shade?"var(--gold)":"var(--surface)"}" stroke="var(--ink)" stroke-width="4"/>`;return s+"</svg>"}function numLine(parts,dot,letters){const w=560,x0=40,x1=520,y=50;let s=`<svg viewBox="0 0 ${w} 120" width="${w}" role="img" aria-label="Number line from 0 to 1 in ${parts} equal parts"><line x1="${x0}" y1="${y}" x2="${x1}" y2="${y}" stroke="var(--ink)" stroke-width="4"/>`;for(let k=0;k<=parts;k++){const x=x0+(x1-x0)*k/parts,end=k===0||k===parts;s+=`<line x1="${x}" y1="${y-(end?20:13)}" x2="${x}" y2="${y+(end?20:13)}" stroke="var(--ink)" stroke-width="4"/>`;const lab=k===0?"0":k===parts?"1":letters?"ABCDEFG"[k-1]:"";if(lab)s+=`<text x="${x}" y="${y+52}" font-size="26" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle">${lab}</text>`}if(dot!=null)s+=`<circle cx="${x0+(x1-x0)*dot/parts}" cy="${y}" r="12" fill="var(--coral)"/>`;return s+"</svg>"}function areaGrid(c,r){const u=52;let s=`<svg viewBox="0 0 ${c*u+8} ${r*u+8}" width="${c*u+8}" role="img" aria-label="Rectangle made of ${c} by ${r} unit squares">`;for(let x=0;x<c;x++)for(let y=0;y<r;y++)s+=`<rect x="${4+x*u}" y="${4+y*u}" width="${u}" height="${u}" fill="var(--sea-soft)" stroke="var(--ink)" stroke-width="3"/>`;return s+"</svg>"}function starArray(rows,cols){let s=`<svg viewBox="0 0 ${cols*70+20} ${rows*70+20}" width="${cols*70+20}" role="img" aria-label="${rows} rows of ${cols} stars">`;for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){s+=window.TP_ICON_G?window.TP_ICON_G("star",c*70+45,r*70+40,52):""}return s+"</svg>"}function noteBoxes(){const box=t=>`<div style="border:3px dashed var(--line);border-radius:16px;min-width:240px;min-height:110px;padding:8px 16px;background:var(--surface)"><p class="fig-label" style="margin:0;font-size:1.5rem">${t}</p></div>`;return`<div class="figure">${box("Fur")}${box("Food")}</div>`}const PLOT_TICKS=["2","2 1/4","2 1/2","2 3/4","3","3 1/4","3 1/2","3 3/4","4"];function plotSvg(){const seq=E.state.barPlot||[],W=700,x0=60,x1=640,base=150,X=i=>x0+(x1-x0)*i/8;let s=`<svg viewBox="0 0 ${W} ${base+80}" width="${W}" role="img" aria-label="Line plot from 2 to 4 inches, marked in fourths of an inch">`;s+=`<line x1="${x0-24}" y1="${base}" x2="${x1+24}" y2="${base}" stroke="var(--ink)" stroke-width="4"/>`;PLOT_TICKS.forEach((t,i)=>{const x=X(i),whole=i%4===0,c=seq.filter(v=>v===i).length;s+=`<line x1="${x}" y1="${base-(whole?15:10)}" x2="${x}" y2="${base+(whole?15:10)}" stroke="var(--ink)" stroke-width="${whole?4:3}"/>`;s+=`<text x="${x}" y="${base+42}" font-size="${whole?24:19}" font-weight="700" text-anchor="middle" fill="var(--ink)">${t}</text>`;for(let k=0;k<c;k++)s+=`<text x="${x}" y="${base-24-k*34}" font-size="34" font-weight="700" text-anchor="middle" fill="var(--sea)">✕</text>`;s+=`<rect class="pc" data-i="${i}" x="${x-34}" y="4" width="68" height="${base+50}" fill="transparent" style="cursor:pointer"/>`});s+=`<text x="${W/2}" y="${base+70}" font-size="18" font-weight="700" text-anchor="middle" fill="var(--ink)">Gold bar lengths in inches</text>`;return s+"</svg>"}const STOPS=[{id:1,title:"Word Flip",parts:[{std:["RF.3.3"],kind:"words",words:WORDS,n:12,dur:90,dir:"Read each word out loud. The last two are silly words. Just sound them out.",desc:"reading words with prefixes, suffixes, many syllables, and irregular spellings",key:["Read each word. mistrandful and replomable are silly words: listen for the prefix, the middle, and the suffix (mis-trand-ful, re-plom-a-ble).","Watch for: prefixes (pre-, dis-), suffixes (-less, -able, -ous), Latin suffix -tion (invention, celebration), multisyllable words (comfortable, remember), irregular words (thought, enough)."]}]},{id:2,title:"Read the Story",short:"Read",parts:[{std:["RF.3.4"],kind:"read",n:0,label:"words read correctly",dur:175,dir:"Read the story out loud. Use your best reading voice.",desc:"a grade-level story read aloud",html:()=>`<p class="passage">${FABLE}</p>`,key:["__WC__ words. Time 1 minute and mark errors and self-corrections on your own copy. Let the student finish the passage.","Fall grade 3 benchmark: about 83 words correct per minute (Hasbrouck and Tindal 2017, fall 50th percentile). The passage length is set from the highest grade 3 figure on that same table, the spring 90th percentile of about 166 words correct per minute, so the minute ends before the text does even for the fastest reader and the score measures the reading rather than the length of the page.","Note pace and expression."]}]},{id:3,title:"Story Questions",short:"Story Qs",parts:[{title:"Prove It",std:["RL.3.1"],dur:120,dir:"Answer out loud. Look back at the story to find your answer.",desc:"story questions answered with evidence from the text",html:()=>`<p class="passage sm">${FABLE}</p>`,qs:["How did Nora feel before she went on stage? Find the words in the story that show it.",`What did ${BRO} do to help Nora? Use the story to answer.`,"How did Nora’s singing change during her song? Find the sentence that tells you."],key:["Nervous or scared. Points to “butterflies in her stomach,” “I can’t do it,” or “My legs feel like jelly.” (RL.3.1)","He told her to look at him in the front row and pretend they were at home, and he waved both arms from his seat. (RL.3.1)","It started quiet and got stronger. Points to “Her voice was quiet at first, but it grew stronger with every line.” (RL.3.1)"]},{title:"Word Meanings",std:["RL.3.4"],dur:75,dir:"Answer out loud.",desc:"literal and nonliteral word and phrase meanings in a story",qs:["Nora had “butterflies in her stomach.” What does that mean? Were there real butterflies?",`${BRO} said the song would be “a piece of cake.” What did he mean?`,"Which sentence means exactly what it says? A: “All that waving made me hungry enough to eat a horse.” B: “The lights were bright and hot.”"],key:["She felt nervous. No real butterflies: it is not literal. (RL.3.4)","It would be easy. (RL.3.4)","B is literal. A is an exaggeration that means very hungry. (RL.3.4)"]}]},{id:4,title:"Two Texts",parts:[{title:"Use the Text",std:["RI.3.1"],n:3,dur:145,dir:"Read both texts to yourself. Then answer out loud.",desc:"questions about an informational text answered from the text",html:()=>twoTextsHtml(),qs:["Why do sea otters clean their fur so often? Use Text 1 to answer.","How does an otter open a shell? Use Text 2 to answer.","Most sea animals have something to keep them warm. Text 1 says so. A sea otter does not have it. What is it?"],key:["Clean fur traps tiny bubbles of air next to the skin, and the air keeps the cold water out. Answer comes from Text 1. (RI.3.1)","It floats on its back and uses a rock to crack the shell. Answer comes from Text 2. (RI.3.1)","A thick layer of fat. Text 1 says most sea animals have one and sea otters do not. Answer comes from Text 1. Partial: naming the thick fur, which is what the otter does have, answers a different question and does not count. (RI.3.1)"]},{title:"Same and Different",std:["RI.3.9"],n:3,dur:85,dir:"Think about both texts. Answer out loud.",desc:"comparing and contrasting two texts on the same topic",qs:["Both texts tell how sea otters stay warm. What is the same in both texts? What is different?","Say the most important point of Text 1 in one sentence. Then say the most important point of Text 2 in one sentence."],key:["Same: both say otters live in cold water and need to stay warm. (RI.3.9, compare)","Different: Text 1 says thick, clean fur traps air. Text 2 says eating a lot of food gives the body energy to stay warm. (RI.3.9, contrast)","Text 1: an otter's thick, clean fur traps air next to the skin and that keeps the cold water out. Text 2: an otter eats a great deal every day, and that food gives its body the energy to stay warm. Both points is the full response. Partial: one of the two most important points given, or a small detail offered in place of the main point, is approaching. (RI.3.9, most important points)"]}]},{id:5,title:"Note Catcher",parts:[{std:["W.3.8"],n:3,label:"checks met",dur:90,dir:"Look back at the two texts. Write your notes on your paper and hold it up.",desc:"taking brief notes from two texts and sorting them into given categories",html:()=>`${twoTextsHtml()}<p class="big">Make two boxes on your paper. Label them Fur and Food. Write one short note from the texts in each box.</p>${noteBoxes()}<p class="small" style="text-align:center;font-size:1.2rem">A note is just a few words. You do not need a whole sentence.</p>`,key:["Fur box: a fact from Text 1, such as thickest fur of any animal, no layer of fat, cleans fur for hours, clean fur traps air, air keeps cold water out. (W.3.8, gathers information and sorts it)","Food box: a fact from Text 2, such as eats one fourth of its body weight each day, dives for crabs, clams, and sea urchins, cracks shells with a rock, food gives energy to stay warm. (W.3.8, gathers information and sorts it)","Notes are brief: a few words or a short phrase in the student’s own words, not a whole sentence copied from the text. (W.3.8, brief notes)"]}]},{id:6,title:"Listen Up",parts:[{std:["SL.3.2"],n:3,label:"checks met",dur:90,dir:"Listen to your teacher read. Then answer out loud.",desc:"the main idea and two details of a text read aloud",html:()=>`<p class="huge" aria-hidden="true">${F.icon("moon",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read about the moon. Then tell the main idea and two details.</p>`,read:MOON,key:["Main idea: the moon looks like it changes shape because we see different amounts of its sunny side as it moves around Earth. (SL.3.2)","Detail 1, such as: the moon does not make its own light; it goes around Earth about once a month; full moon is the whole sunny side. (SL.3.2)","Detail 2, a different one from the list above or the new moon detail. (SL.3.2)"]}]},{id:7,title:"Fix It Fast",short:"Fix It",parts:[{title:"Grammar",std:["L.3.1"],dur:75,dir:"Say each sentence out loud with the correct word.",desc:"spoken grammar items (verb tense, comparing words, agreement, joining sentences)",qs:["The children ____ to the bus yesterday. (run)","Tomorrow she ____ a cake. (bake)","This is the ____ tree in the whole park. (tall)","The dogs ____ every night. (bark or barks)","Join these with one word: I wanted to play outside. It was raining."],key:["ran (L.3.1, irregular past tense)","will bake (L.3.1, simple future)","tallest (L.3.1, superlative)","bark (L.3.1, subject-verb agreement)","I wanted to play outside, but it was raining. (L.3.1, conjunction)"]},{title:"Word Parts",std:["RF.3.3"],dur:30,dir:"Answer out loud.",desc:"meanings of words with a prefix or suffix",qs:["What does misread mean?","What does careless mean?"],key:["To read something wrong. mis- means wrong or badly. (RF.3.3)","Without care, not careful. -less means without. (RF.3.3)"]}]},{id:8,title:"Tell Me About It",short:"Tell Me",parts:[{std:["SL.3.4"],n:3,label:"checks met",dur:75,dir:"Talk for about one minute. Speak clearly.",desc:"reporting on a topic with facts and details, speaking clearly",html:()=>`<p class="big">Tell me about an animal you know a lot about.</p><div class="row center" style="margin-top:20px;gap:18px"><span class="pill" style="font-size:1.4rem">What it is</span><span class="pill" style="font-size:1.4rem">Facts</span><span class="pill" style="font-size:1.4rem">Details</span></div>`,key:["Gives facts that fit the topic (SL.3.4)","Adds relevant, descriptive details (SL.3.4)","Speaks clearly at a pace you can follow (SL.3.4)"]}]},{id:9,title:"Groups and Shares",short:"Groups",parts:[{title:"Multiply",std:["3.OA.A.1"],n:3,dur:85,dir:"Look at the stars. Write your equation on your paper and hold it up. Say your story problem out loud.",desc:"explaining multiplication as equal groups",fig:()=>`<div class="figure">${starArray(3,5)}</div>`,qs:["Write a multiplication equation for this picture. What does each number mean?","Tell a story problem for 4 × 6.","A net holds 7 shells. There are 5 nets. Write the multiplication equation. What does the 5 stand for. What does the 7 stand for?"],key:["3 × 5 = 15: 3 rows (groups) of 5 stars, 15 in all. 5 × 3 = 15 read as 5 columns of 3 is also correct. Partial: the equation right with no meaning for each number is approaching. (3.OA.A.1)","A story with 4 equal groups of 6, or 6 groups of 4, 24 in all. Partial: a story with the right numbers but no equal groups is approaching. (3.OA.A.1)","5 × 7 = 35. The 5 is the number of nets, which is the number of groups, and the 7 is the shells in each net, which is how many are in one group. Or: 7 × 5 = 35 counts as well, as long as the student says which number is the groups and which is the size of a group. Partial: 35 right with no meaning given for the 5 and the 7 is approaching. (3.OA.A.1)"]},{title:"Divide",std:["3.OA.A.2"],n:3,dur:85,dir:"Say your story problem out loud.",desc:"explaining division as equal shares or equal groups",qs:["Tell a story problem for 20 ÷ 5. What does the answer mean in your story?","28 shells are packed into bags with 7 shells in each bag. Write the division equation. What does the answer count?"],key:["A story where 20 things are shared into 5 equal groups, or put into groups of 5. Partial: a story with the right numbers but no equal sharing is approaching. (3.OA.A.2)","Says the 4 is the number in each group, or the number of groups, to match the story. Partial: naming 4 with no match to the story is approaching. (3.OA.A.2)","28 ÷ 7 = 4. The 4 counts the bags, not the shells in a bag, because this story gives the size of each share and asks how many shares there are. Partial: 4 right with nothing said about what it counts, or the 4 named as shells in a bag, is approaching. (3.OA.A.2)"]}]},{id:10,title:"Round It",parts:[{std:["3.NBT.A.1"],dur:60,dir:"Say each answer out loud.",desc:"rounding to the nearest 10 and 100",qs:["Round 67 to the nearest 10.","Round 342 to the nearest 10.","Round 342 to the nearest 100.","Round 850 to the nearest 100."],key:["70. Partial: 60 rounds down when the ones digit is 7 and does not count. (3.NBT.A.1)","340. Partial: 350 rounds up when the ones digit is 2 and does not count. (3.NBT.A.1)","300. Partial: 400 rounds up when the tens digit is 4 and does not count. (3.NBT.A.1)","900. Partial: 800 rounds down at the halfway mark and does not count. (3.NBT.A.1)"]}]},{id:11,title:"Two-Step Problems",short:"Two Steps",parts:[{std:["3.OA.D.8"],n:4,dur:150,dir:"Solve on your paper. Show your work and hold it up.",desc:"two-step word problems with an equation and an estimate",qs:["Mia has 3 packs of pencils with 8 pencils in each pack. She gives 7 pencils to her class. How many pencils does she have left? Write an equation with a letter for the unknown. Then solve.","A school ordered 198 red shirts and 305 blue shirts. Then 96 shirts were handed out. How many shirts are left? Estimate first. Then solve."],key:["Problem 1 equation with a letter: 3 × 8 − 7 = p, or 3 × 8 = 24 and 24 − 7 = p. Partial: the right answer with no letter for the unknown is approaching. (3.OA.D.8)","Problem 1 answer: 17 pencils. Partial: 24 stops at the packs and leaves the 7 out, so it is approaching. (3.OA.D.8)","Problem 2 estimate: about 200 + 300 − 100 = 400. Partial: any rounding that lands near 400 counts, and no estimate at all is approaching. (3.OA.D.8, rounding to check)","Problem 2 answer: 198 + 305 = 503, then 503 − 96 = 407 shirts. Partial: 503 stops before the shirts are handed out and is approaching. (3.OA.D.8)"]}]},{id:12,title:"Area",parts:[{std:["3.MD.C.7"],n:3,dur:75,dir:"Look at the rectangle. Answer out loud.",desc:"finding area by counting tiles and by multiplying",fig:()=>`<div class="figure">${areaGrid(6,4)}</div>`,qs:["Each small square is 1 square unit. What is the area of this rectangle? How did you find it?","Another rectangle is 7 cm long and 5 cm wide. What is its area?"],key:["24 square units. Partial: 24 with no square unit named is approaching. (3.MD.C.7)","Counts the tiles or rows, or multiplies 6 × 4. Partial: counting the tiles one at a time counts here, and the multiplying is the thing to note. (3.MD.C.7)","35 square cm, from 7 × 5. Partial: 24 cm from adding the sides gives the perimeter and does not count. (3.MD.C.7)"]}]},{id:13,title:"Fraction Shapes",short:"Fractions",parts:[{title:"Fraction Shapes",std:["3.NF.A.1"],n:3,dur:60,dir:"Look at the shapes. Answer out loud.",desc:"naming fractions and unit fractions of a whole",fig:()=>`<div class="figure"><div>${fracRect([0,.25,.5,.75,1],3)}<p class="fig-label">Shape A</p></div><div>${fracRect([0,.13,.4,.78,1],0)}<p class="fig-label">Shape B</p></div></div>`,qs:["Shape A: What fraction is shaded? What fraction is one part?","Shape B: Is this shape split into fourths? Why or why not?"],key:["3/4 is shaded. Partial: 3 given with no fraction form is approaching. (3.NF.A.1)","One part is 1/4. Partial: naming 4 parts with no fraction for one part is approaching. (3.NF.A.1)","No. The 4 parts are not equal, so they are not fourths. Partial: saying no with nothing said about the parts being equal is approaching. (3.NF.A.1)"]},{title:"Equal Parts",std:["3.G.A.2"],n:3,dur:70,dir:"Draw on your paper and hold it up. Then answer out loud.",desc:"splitting a shape into equal parts and naming the unit fraction",qs:["On your paper, draw a rectangle and split it into 6 equal parts. What fraction of the whole is each part?","Now draw a circle and split it into 4 equal parts. What fraction of the whole circle is each part?"],key:["Draws 6 parts that are about equal in area. Partial: 6 parts drawn that are plainly not equal in area is approaching. (3.G.A.2)","Each part is 1/6. Partial: 6 given with no fraction form is approaching. (3.G.A.2)","Draws 4 parts of the circle that are about equal in area and says each part is 1/4 of the whole circle. Or: cuts across the middle both ways, or into four wedges from the center, either is fine. Partial: 4 parts drawn that are plainly not equal in area, or 4 given with no fraction form, is approaching. (3.G.A.2)"]}]},{id:14,title:"Fraction Line",parts:[{title:"Number Line",std:["3.NF.A.2"],n:3,dur:70,dir:"Look at the number lines. Answer out loud.",desc:"fractions on a number line",fig:()=>`<div class="figure"><div>${numLine(4,3,false)}<p class="fig-label">Line 1</p></div><div>${numLine(6,null,true)}<p class="fig-label">Line 2</p></div></div>`,qs:["Line 1: What fraction is at the dot?","Line 2: Which letter is at 2/6?","Line 2: Which letter is at 4/6? How many one-sixth lengths is that from 0?"],key:["3/4. Partial: 3 given with no fraction form is approaching. (3.NF.A.2)","B (3.NF.A.2)","D, and 4 one-sixth lengths from 0. The whole from 0 to 1 is cut into 6 equal lengths, and 4/6 is 4 of them end to end. Partial: the letter right with no count of lengths from 0 is approaching, and counting the tick marks instead of the spaces gives 5 and does not count. (3.NF.A.2)"]},{title:"Compare Fractions",std:["3.NF.A.3"],n:5,dur:90,dir:"Answer out loud. Tell how you know. For the last one, write the fraction on your paper. Then hold it up.",desc:"equivalent fractions and comparing fractions",qs:["1/2 = ?/4. How do you know?","Which is greater: 3/8 or 5/8?","Which is greater: 1/3 or 1/6? Why?","Write 3 as a fraction. What whole number equals 4/4?"],key:["2/4. Explains with a picture, same size, or same point on a number line. Partial: 2/4 right with no explanation is approaching. (3.NF.A.3)","5/8: same size parts, more of them. Partial: naming 5/8 with no reason is approaching. (3.NF.A.3)","1/3: fewer parts in the whole, so each part is bigger. Partial: naming 1/3 with no reason is approaching. (3.NF.A.3)","3 = 3/1. Or: 6/2, or any fraction worth 3, counts as well. (3.NF.A.3)","4/4 = 1. Partial: 4 counts the parts instead of the whole and does not count. (3.NF.A.3)"]}]},{id:15,title:"Measure and Plot",short:"Measure",parts:[{title:"Measure It",std:["3.MD.B.4"],dur:105,dir:"Look at the rulers. Each ruler shows inches. Say each length out loud. For the last one, get a ruler and measure.",mats:["a ruler"],desc:"measuring lengths to the nearest half and fourth of an inch, including generating measurements of real objects with a ruler",fig:()=>F.row([F.ruler({length:4,px:100,item:2.5,itemLabel:"Gold bar A",parts:4}),"Ruler 1"],[F.ruler({length:4,px:100,item:3.25,itemLabel:"Gold bar B",parts:4}),"Ruler 2"]),qs:["How long is gold bar A?","How long is gold bar B?","Now you are the measurer. Find three small things at your table. Something like a pencil. Or an eraser. Or a paper clip. Measure each one with your ruler. Say what each thing is. Say how long it is, to the nearest quarter inch."],key:["2 1/2 inches. The bar ends on the half-inch mark between 2 and 3. Partial: 2 inches or 3 inches rounds to a whole and is approaching. (3.MD.B.4)","3 1/4 inches. The bar ends on the first small mark after 3. Partial: 3 inches rounds to a whole and is approaching. (3.MD.B.4)","Three objects of the student's own choosing, each measured and named with a length. Watch the 0 end of the ruler line up with the end of the object, and listen for a length to the nearest quarter inch (a whole, 1/4, 1/2, or 3/4) with the unit inches said. Write the three objects and lengths on the record sheet, and have the student hold one object on the ruler up to the camera so you can check that reading yourself. Or: any three objects count, since these are the student's own data and there is no fixed answer. Partial: three lengths given but all rounded to whole inches, or the ruler started at the 1 instead of the 0, is approaching. (3.MD.B.4)"]},{title:"Plot It",std:["3.MD.B.4"],n:2,dur:60,dir:"Tell your teacher where each X goes. Your teacher will click for you.",desc:"showing measurement data on a line plot marked in fourths of an inch",html:()=>`<p class="big" style="margin-top:0">Here are four more gold bars. Put all six gold bars on the line plot.</p>${F.table(["Gold bar","C","D","E","F"],[["Length in inches","3","3","2 3/4","3"]])}`,render:()=>`<div style="text-align:center">${plotSvg()}<div class="row center" style="margin:4px 0 12px"><button class="btn ghost" data-plot="undo">Undo last X</button><button class="btn ghost" data-plot="clear">Clear</button></div></div>`,bind:(root,ctx)=>{root.querySelectorAll(".pc").forEach(r=>r.onclick=()=>{const i=+r.dataset.i,seq=E.state.barPlot=E.state.barPlot||[];if(seq.filter(v=>v===i).length<4)seq.push(i);E.save();ctx.redraw()});root.querySelectorAll("[data-plot]").forEach(b=>b.onclick=()=>{const seq=E.state.barPlot=E.state.barPlot||[];if(b.dataset.plot==="clear")seq.length=0;else seq.pop();E.save();ctx.redraw()})},qs:["Where does the X go for each gold bar? Use bars A, B, C, D, E, and F."],key:["How to mark: click above a number on the line plot to add an X as the student tells you. Use Undo last X to fix a click.","Whole inches: three Xs stacked above 3, for bars C, D, and F. Partial: two of the three Xs placed right is approaching. (3.MD.B.4)","Halves and fourths: one X above 2 1/2 for bar A, one above 2 3/4 for bar E, and one above 3 1/4 for bar B. If A or B was measured wrong, count the X as right when it matches the student’s own measurement. Partial: two of the three Xs placed right is approaching. (3.MD.B.4)"]}]},{id:16,title:"Write About It",short:"Write",parts:[{alt:{group:"write",key:"opinion",label:"Opinion",icon:"💬",hint:"Tell what you think about Nora’s brother"},std:["W.3.1","L.3.1"],n:5,label:"checks met",dur:300,dir:"Write on your paper. When you finish, hold it up or read it to your teacher.",desc:"an opinion writing piece",html:()=>`<p class="big">Was ${BRO} a good brother? Write your opinion. Give reasons from the story. Write 4 or 5 sentences.</p><ul class="qlist" style="margin-top:14px"><li>Say your opinion</li><li>Give reasons</li><li>Use a linking word: because, since, for example</li><li>End with a closing sentence</li></ul><details class="look-back" open><summary>Look back at the story</summary><p class="passage sm">${FABLE}</p></details>`,key:["Introduces the topic and states an opinion (W.3.1)","Gives reasons that support the opinion (W.3.1)","Uses linking words like because, since, for example, therefore (W.3.1)","Ends with a concluding sentence (W.3.1)","Complete sentences with correct verb tenses and subject-verb agreement (L.3.1)"]},{alt:{group:"write",key:"facts",label:"Facts",icon:"📘",hint:"Teach how sea otters stay warm"},std:["W.3.2","L.3.1"],n:5,label:"checks met",dur:300,dir:"Write on your paper. When you finish, hold it up or read it to your teacher.",desc:"an informative writing piece",html:()=>`<p class="big">Write to teach someone how sea otters stay warm. Use facts from the two texts. Write 4 or 5 sentences.</p><ul class="qlist" style="margin-top:14px"><li>Name your topic</li><li>Give facts and details</li><li>Use a linking word: also, another, and, but</li><li>End with a closing sentence</li></ul><details class="look-back" open><summary>Look back at the two texts</summary>${twoTextsHtml()}</details>`,key:["Introduces the topic: how sea otters stay warm (W.3.2)","Develops the topic with facts and details from the texts, such as thick fur, clean fur traps air, eating a lot gives energy (W.3.2)","Uses linking words like also, another, and, more, but (W.3.2)","Ends with a concluding sentence (W.3.2)","Complete sentences with correct verb tenses and subject-verb agreement (L.3.1)"]},{alt:{group:"write",key:"story",label:"Story",icon:"✨",hint:"Tell about a time you felt nervous"},std:["W.3.3","L.3.1"],n:5,label:"checks met",dur:300,dir:"Write on your paper. When you finish, hold it up or read it to your teacher.",desc:"a narrative writing piece",html:()=>`<p class="big">Write about a time you felt nervous, like Nora. It can be real or made up. Write 4 or 5 sentences.</p><div class="row center" style="margin-top:20px;gap:18px"><span class="pill" style="font-size:1.4rem">First</span><span class="pill" style="font-size:1.4rem">Next</span><span class="pill" style="font-size:1.4rem">Last</span></div>`,key:["Sets up the situation and who is in the story (W.3.3)","Events happen in a clear order, with time words like first, then, after that (W.3.3)","Tells actions, thoughts, or feelings, or uses dialogue (W.3.3)","Has an ending that wraps it up (W.3.3)","Complete sentences with correct verb tenses and subject-verb agreement (L.3.1)"]}]},{id:17,title:"Senses and Signals",short:"Senses",parts:[{title:"Sense, Brain, Act",std:["3-LS1-1"],n:3,dur:90,dir:"Answer out loud. For the last one, draw your model on your paper. Then hold it up.",desc:"using a model to show how an animal takes in information, processes it, and responds",html:()=>`<p class="big">The ship’s cat is asleep on the warm planks of the dock. A parrot lands behind her. She turns her head toward the sound.</p>
     <div class="figure">${F.icon("cat",96)}${F.icon("ear",80)}${F.icon("parrot",96)}</div>`,qs:["Which body part took in the information about the parrot?","Something happens between hearing the sound and turning her head. What is it, and which body part does that work?","Draw a model of this with three boxes and two arrows. Label every box."],key:["Her ears. An ear is a sense organ, and it takes in sound. (3-LS1-1)","The information travels to her brain, and the brain works out what it means and decides what to do. (3-LS1-1)","Three parts in order, with arrows: ear or hears the parrot, then brain, then turns her head. The order is what is rated, not the drawing. A model that jumps straight from ear to turning, with no brain in the middle, is incomplete. (3-LS1-1)"]},{title:"Why Groups Help",std:["3-LS2-1"],n:3,dur:75,dir:"Look at the table. Answer out loud.",desc:"building an argument from data that forming a group helps animals survive",html:()=>`<p class="big">The crew counted fish caught by dolphins off the reef for one hour.</p>
     <table class="bigTable"><tr><th>Dolphins</th><th>Fish caught by each dolphin</th></tr>
     <tr><td>one dolphin hunting alone</td><td>3</td></tr>
     <tr><td>a pod of six dolphins hunting together</td><td>7</td></tr></table>
     <div class="figure">${F.icon("dolphin",96)}${F.icon("fish",72)}</div>`,qs:["Which dolphins caught more fish each?","Make an argument that being in a pod helps a dolphin survive. Use a number from the table.","Name one other way living in a group could help an animal stay alive."],key:["The ones in the pod, 7 fish each against 3 for the dolphin alone. (3-LS2-1)","The claim yes, with the numbers attached: each dolphin in the pod got 7 fish and the one alone got 3, so a dolphin in a pod gets more food. A yes with no number from the table is not yet an argument. (3-LS2-1)","Any sound second reason: more animals watching for danger, warning each other, help raising young, taking turns resting, sharing warmth. (3-LS2-1)"]}]},{id:18,title:"Traits from Parents",short:"Traits",parts:[{title:"Passed Down and Shaped",std:["3-LS3-1","3-LS3-2"],n:4,dur:120,dir:"Look at both tables. Answer out loud.",desc:"reading trait data for parents and offspring, naming the variation, and telling when the surroundings shaped a trait",html:()=>`<p class="big">Table 1: a pair of green parrots on the island and their four chicks.</p>
     <table class="bigTable"><tr><th>Bird</th><th>Tail color</th><th>Tail length in cm</th></tr>
     <tr><td>parent 1</td><td>green</td><td>10</td></tr><tr><td>parent 2</td><td>green</td><td>12</td></tr>
     <tr><td>chick A</td><td>green</td><td>9</td></tr><tr><td>chick B</td><td>green</td><td>11</td></tr>
     <tr><td>chick C</td><td>green</td><td>8</td></tr><tr><td>chick D</td><td>green</td><td>12</td></tr></table>
     <p class="big">Table 2: two palm seedlings grown from seeds off the same parent tree.</p>
     <table class="bigTable"><tr><th>Seedling</th><th>Where it grew</th><th>Height in cm</th></tr>
     <tr><td>seedling 1</td><td>open sand, full sun</td><td>40</td></tr>
     <tr><td>seedling 2</td><td>under a rock ledge, deep shade</td><td>18</td></tr></table>`,qs:["Both parents have green tails and so does every chick. What does that tell you about where the color came from?","The four chicks do not have tails of the same length. What is that difference called. Does it mean one of them is not their chick?","In Table 2, both seeds came off the same parent tree. What made the difference in height?","So is a palm’s height decided only by its parent tree? Explain."],key:["It was inherited from the parents. A trait both parents have and every offspring has is passed down. (3-LS3-1)","Variation. They are all still their chicks: inherited traits vary from one offspring to the next, so a group of similar organisms is not identical. (3-LS3-1)","How much sunlight each one got. Same parent tree, different surroundings, different height. (3-LS3-2)","No. The environment shaped it as well. Listen for the idea that a trait can be influenced by where a living thing grows, not by inheritance alone. (3-LS3-2)"]}]},{id:19,title:"Long Ago and Living Now",short:"Fossils",parts:[{title:"Clues in the Cliff",std:["3-LS4-1"],n:3,dur:90,dir:"Look at the table of rock layers. Answer out loud.",desc:"reading fossil data to say which organisms lived in a place and what the place was like",html:()=>`<p class="big">The crew dug into a cliff above the beach and wrote down the fossils in each layer. The top layer is the youngest.</p>
     <table class="bigTable"><tr><th>Layer</th><th>Fossils found</th></tr>
     <tr><td>top</td><td>fern leaf prints, a beetle wing</td></tr>
     <tr><td>middle</td><td>fish bones, clam shells</td></tr>
     <tr><td>bottom</td><td>coral, sea urchin spines</td></tr></table>
     <div class="figure">${F.icon("shell",80)}${F.icon("fish",80)}${F.icon("leaf",80)}</div>`,qs:["Name two organisms that lived where this cliff now stands.","What kind of place was the bottom layer, dry land or shallow sea? Use the fossils as your evidence.","The top layer has ferns and a beetle but no sea animals at all. What does that tell you changed here?"],key:["Any two the table names: a fern, a beetle, a fish, a clam, coral, a sea urchin. (3-LS4-1)","A shallow sea. Coral and sea urchins live in sea water, and naming them is the evidence. An answer with no fossil named is not yet using the data. (3-LS4-1)","The environment changed from sea to land. The sea animals stop appearing and land plants and insects start, so this place was no longer underwater. (3-LS4-1)"]},{title:"A Useful Difference",std:["3-LS4-2"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"explaining how a variation among individuals of one species gives an advantage",html:()=>`<p class="big">Shore crabs on this beach eat snails, and a snail has to be cracked open first. The crew measured claws and counted shells.</p>
     <table class="bigTable"><tr><th>Crabs</th><th>Claw width</th><th>Shells opened in a day</th></tr>
     <tr><td>narrow claws</td><td>2 cm</td><td>3</td></tr>
     <tr><td>wide claws</td><td>4 cm</td><td>9</td></tr></table>
     <div class="figure">${F.icon("crab",96)}${F.icon("shell",72)}</div>`,qs:["Which crabs opened more shells in a day?","Explain why a wider claw is an advantage for a crab on this beach. Use the table.","The wide-clawed crabs also raised more young. How can a trait that helps a crab eat end up giving it more young?"],key:["The wide-clawed crabs, 9 shells against 3. (3-LS4-2)","A wider claw cracks more shells, so the crab gets more food on a beach where the food is locked inside shells, and it is more likely to survive. The explanation has to lean on the data. (3-LS4-2)","More food means it stays healthy and lives longer, so it has more chances to find a mate and raise young. Accept any version that links surviving to finding mates or reproducing. (3-LS4-2)"]}]},{id:20,title:"When the Lagoon Changed",short:"Habitat",parts:[{title:"Who Survives, and What Would Help",std:["3-LS4-3","3-LS4-4"],n:4,dur:120,dir:"Read the table. Answer out loud.",desc:"arguing from data who can survive in a changed habitat, then judging the merit of a solution",html:()=>`<p class="big">A storm pushed a long sand bar across the mouth of the lagoon. Cool sea water no longer flows in, and the lagoon is now warm and shallow. The crew checked it every month for a year.</p>
     <table class="bigTable"><tr><th>Living thing</th><th>What happened after the change</th></tr>
     <tr><td>eelgrass</td><td>grew thickly across the whole lagoon</td></tr>
     <tr><td>spotted shore fish</td><td>fewer counted every month</td></tr>
     <tr><td>reef crab</td><td>none found at all</td></tr></table>`,qs:["Which living thing survived well in the changed lagoon? Give the evidence.","Which one could not survive there at all. Which one survived less well?","The crew wants to cut a channel. It goes through the sand bar. Then cool sea water flows in again. Would that help the reef crab? Name one drawback of the plan.","A second plan is to carry the reef crabs away. They would go to a cooler bay down the coast. Which plan has more merit? Why?"],key:["The eelgrass. It grew thickly in warm shallow water, so the change suited it. (3-LS4-3)","The reef crab could not survive at all, none were found. The spotted shore fish survived less well, fewer every month. (3-LS4-3)","Yes, because cool sea water is what the crab needs and the channel brings it back. Then any real drawback: the eelgrass that is thriving now may thin out, the channel can fill with sand in the next storm, it is a lot of digging. A claim with no drawback is half of this standard. (3-LS4-4)","Either plan can earn credit. What is rated is the reasoning: the channel repairs the habitat for everything that lives in it, while moving the crabs helps only the crabs, and the new bay may already be full or may be too far to carry them. (3-LS4-4)"]}]},{id:21,title:"Weather and Climate",short:"Weather",parts:[{title:"A Season of Weather",std:["3-ESS2-1"],n:3,dur:90,dir:"Look at the table. Answer out loud. For the last one, draw your graph on your paper. Then hold it up.",desc:"reading and making a graphical display of typical weather for one season",html:()=>`<p class="big">The island has a wet season. Here are the rainy days counted in each of its four months.</p>
     <table class="bigTable"><tr><th>Month</th><th>Rainy days</th></tr>
     <tr><td>first</td><td>14</td></tr><tr><td>second</td><td>18</td></tr>
     <tr><td>third</td><td>21</td></tr><tr><td>fourth</td><td>12</td></tr></table>
     <div class="figure">${F.icon("rain",88)}${F.icon("cloud",88)}</div>`,qs:["Which month of the wet season had the most rainy days?","About how many rainy days does a typical month of this wet season have? Use the table.","Draw a bar graph of the four months. Label both sides."],key:["the third month, 21 rainy days (3-ESS2-1)","About 16. Anything from 14 to 18 counts if the student used the numbers. The point is a typical value for the season, not one single month. (3-ESS2-1)","Four bars in month order with heights that match 14, 18, 21 and 12, a label on the month side and a label on the rainy-days side. A graph with no labels is incomplete. (3-ESS2-1)"]},{title:"Two Parts of the World",std:["3-ESS2-2"],n:3,dur:75,dir:"Look at the table. Answer out loud.",desc:"combining information to describe the climates of two different regions of the world",html:()=>`<p class="big">Two places, far apart on the globe.</p>
     <table class="bigTable"><tr><th>Region</th><th>Warm season average</th><th>Cool season average</th><th>Rain in a year</th></tr>
     <tr><td>this island, near the middle of the globe</td><td>29 C</td><td>26 C</td><td>190 cm</td></tr>
     <tr><td>a high mountain region, far from the middle</td><td>14 C</td><td>4 C below zero</td><td>60 cm</td></tr></table>
     <div class="figure">${F.icon("island",88)}${F.icon("mountain",88)}</div>`,qs:["Which region is warm all year long?","In which region would you expect snow. What in the table tells you?","Give one reason why two places on the same globe end up with different climates."],key:["the island, 29 C in its warm season and 26 C in its cool season (3-ESS2-2)","The mountain region. Its cool season average is below freezing, 4 C below zero, so water there turns to ice and snow. (3-ESS2-2)","Any sound reason: how near the place is to the middle of the globe, how high above sea level it is, how near it is to an ocean. One solid reason is enough here. (3-ESS2-2)"]},{title:"Ready for the Storm",std:["3-ESS3-1"],n:3,dur:90,dir:"Answer out loud.",desc:"making a claim about the merit of a design that reduces the impact of a weather hazard",html:()=>`<p class="big">A big storm pushes sea water up the beach. Water runs across the sand. It soaks everything in the camp. The crew decides to rebuild the sleeping huts on posts. The posts hold them one meter above the sand.</p>
     <div class="figure">${F.icon("wave",88)}${F.icon("cabin",88)}</div>`,qs:["Which weather hazard is this design meant to reduce?","Make a claim. Does raising the huts on posts have merit? Give your reason.","Name one thing this design does not protect against."],key:["flooding, from a storm pushing sea water up the beach (3-ESS3-1)","Yes, with a reason attached: water running across the sand passes underneath the floor instead of into it. A yes with no reason is not yet a claim. (3-ESS3-1)","Any real limit: strong wind, rain through the roof, posts washing loose in soft sand, water higher than one meter, the ladder being hard to climb with supplies. (3-ESS3-1)"]}]},{id:22,title:"Forces and Motion",short:"Forces",parts:[{title:"Balanced or Not",std:["3-PS2-1"],n:4,dur:105,dir:"Answer out loud.",desc:"planning an investigation of balanced and unbalanced forces acting on an object",html:()=>`<p class="big">A heavy supply crate sits on the sand with a rope tied to each end. Two crews pull, one on each rope, in opposite directions. The crate does not move.</p>
     <div class="figure">${F.icon("box",96)}${F.icon("hands",88)}</div>`,qs:["Are the forces on the crate balanced or unbalanced? How do you know?","One crew lets go of its rope. What happens to the crate. What changed about the forces?","Plan an investigation to find out. It takes a pull to start this crate moving. How hard a pull? What will you change? What will you measure?","What will you keep the same every time you test?"],key:["Balanced. Equal pulls in opposite directions add up to no change in motion, and the crate staying still is the evidence. (3-PS2-1)","It moves toward the crew that is still pulling. The forces are now unbalanced. (3-PS2-1)","A plan with one thing changed and one thing measured: add one person or one weight to a rope at a time (the change), and watch for the pull at which the crate first slides, or measure how far it slides (the measure). (3-PS2-1)","Any controlled variable that fits the plan: the same crate, the same load inside it, the same patch of sand, the same rope, pulling in the same direction. (3-PS2-1)"]},{title:"Predict the Next Roll",std:["3-PS2-2"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"using a pattern in motion data to predict where an object will be later",html:()=>`<p class="big">A barrel rolls along the flat planks of the dock. The crew marked where it was at the end of each second.</p>
     <table class="bigTable"><tr><th>Seconds</th><th>Distance from the start</th></tr>
     <tr><td>1</td><td>3 m</td></tr><tr><td>2</td><td>6 m</td></tr><tr><td>3</td><td>9 m</td></tr></table>`,qs:["Describe the pattern in the table.","Where will the barrel be at 5 seconds? How do you know?","What could happen that would make your prediction wrong?"],key:["It travels 3 m in every second, the same distance each time. (3-PS2-2)","15 m, because five seconds of 3 m each is 15 m. The reason has to be the pattern, not a guess. (3-PS2-2)","A new force acting on the barrel: the planks turn rough or tilt, something blocks it, someone pushes or stops it, it rolls off the end. A pattern only predicts while nothing changes. (3-PS2-2)"]}]},{id:23,title:"Pulling Without Touching",short:"Magnets",parts:[{title:"Ask About the Pull",std:["3-PS2-3"],n:3,dur:90,dir:"Answer out loud. Your two questions have to be questions, not statements.",desc:"asking questions about cause and effect in magnetic interactions between objects not touching",html:()=>`<p class="big">A compass lies flat on the table. When an iron nail is slid across the table toward it, the compass needle swings. The nail never touches the needle. Two magnets brought end to end push each other apart instead of sticking.</p>
     <div class="figure">${F.icon("compass",96)}${F.icon("key",80)}</div>`,qs:["The nail never touches the needle, yet the needle turns. What does that tell you about this force?","Ask two questions about it that you could actually investigate.","The two magnets push apart instead of sticking. What is causing that push?"],key:["The force acts across a distance, with no contact between the objects. (3-PS2-3)","Any two real investigable questions: how close does the nail have to be, does a longer nail swing the needle further, does a copper nail do anything, does a thick book between them change it, what happens if the nail is turned around. A statement is not a question, so ask once more. (3-PS2-3)","The ends facing each other are the same kind of pole, and like poles push apart. Accept it named as a magnetic force between the two magnets. (3-PS2-3)"]},{title:"A Problem for a Magnet",std:["3-PS2-4","3-5-ETS1-1"],n:4,dur:105,dir:"Answer out loud. For the third one you may write your two sentences on your paper.",desc:"defining a design problem that magnets can solve, with criteria for success and constraints",html:()=>`<p class="big">A ring of iron keys slipped off the chest. The keys fell into shallow water between sharp rocks. Reaching in cuts your hands.</p>
     <div class="figure">${F.icon("key",88)}${F.icon("chest",88)}${F.icon("drop",72)}</div>`,qs:["Say the problem in one sentence that begins: The problem is.","Why is a magnet a sensible idea here? Would the same tool lift a wooden spoon dropped in the same spot?","Write two things your tool must do for you to call it a success.","You may use only string, one stick and one magnet. You have ten minutes. What limits does that put on your design?"],key:["A problem statement about lifting iron keys out of shallow water without putting hands between sharp rocks. The problem has to be about the keys and the rocks, not about the chest. (3-PS2-4)","The keys are iron, and a magnet pulls iron without touching it, so it can lift them from outside the rocks. A wooden spoon is not pulled by a magnet, so no. (3-PS2-4)","Two criteria, written as what the tool must do: lift every key, reach the bottom, keep hands out of the rocks, work while wet, hold on all the way up. (3-5-ETS1-1)","Names the limits as limits: only three materials, only one magnet, only ten minutes. Materials, time and cost are the constraints to listen for. (3-5-ETS1-1)"]}]},{id:24,title:"Compare and Test",short:"Design",parts:[{title:"Three Ways to Do It",std:["3-5-ETS1-2"],n:3,dur:90,dir:"Look at the table and the three rules. Answer out loud.",desc:"comparing several possible solutions against stated criteria and constraints",html:()=>`<p class="big">Water has to be carried from the spring to camp. Three carriers are on the table.</p>
     <table class="bigTable"><tr><th>Design</th><th>Holds</th><th>Weight empty</th><th>Water lost on the walk</th></tr>
     <tr><td>clay jar</td><td>8 L</td><td>heavy</td><td>none</td></tr>
     <tr><td>canvas bag</td><td>6 L</td><td>light</td><td>half a cup</td></tr>
     <tr><td>wooden bucket</td><td>10 L</td><td>medium</td><td>three cups</td></tr></table>
     <p class="big">The rules for success: hold at least 6 L, lose no more than one cup on the walk, light enough for one person to carry alone.</p>`,qs:["Which design holds the most water?","Which design meets all three rules? Explain using the table.","Pick a design you would not use. Then name the rule it fails."],key:["the wooden bucket, 10 L (3-5-ETS1-2)","The canvas bag. It holds 6 L, loses only half a cup, and is light. Another choice counts only if the student argues it against all three rules using the table. (3-5-ETS1-2)","Any reasoned rejection with the rule named: the clay jar fails the light-enough rule, the wooden bucket fails the one-cup rule at three cups. Naming the rule is the part being rated. (3-5-ETS1-2)"]},{title:"Make the Test Fair",std:["3-5-ETS1-3"],n:3,dur:90,dir:"Answer out loud.",desc:"judging whether a test is fair, naming controlled variables, and identifying a failure point",html:()=>`<p class="big">Two canvas bags were tested to see which one leaks less.</p>
     <table class="bigTable"><tr><th>Bag</th><th>Water put in</th><th>Path walked</th></tr>
     <tr><td>bag A</td><td>6 L</td><td>flat sand, 100 steps</td></tr>
     <tr><td>bag B</td><td>3 L</td><td>over rocks, 40 steps</td></tr></table>`,qs:["Is this a fair test? Say why.","Name two things to keep the same so the test is fair.","Bag A leaked at the bottom seam on every single walk. Name that weak spot. Then say what you would change about the bag."],key:["No. Two things were different at once, the amount of water and the path, so a leak cannot be pinned on the bag. (3-5-ETS1-3)","Any two controlled variables: the same amount of water, the same path, the same number of steps, the same carrier, the same weather. (3-5-ETS1-3)","The failure point is the bottom seam. Any improvement aimed at that seam counts: stitch it twice, patch it, move the seam up the side, line the bottom. An improvement somewhere else does not. (3-5-ETS1-3)"]}]},{id:25,title:"Maps and Places",short:"Maps",parts:[{std:["HSS-3.1"],n:4,dur:90,dir:"Use the map grid and the table. Answer out loud.",desc:"using a map grid and a table to describe physical and human features and where they sit",html:()=>`<p class="big">A map grid of the island. North is the top row.</p>
     <table class="bigTable"><tr><th></th><th>west</th><th>middle</th><th>east</th></tr>
     <tr><th>north</th><td>${F.icon("mountain",54)}<br>ridge</td><td>${F.icon("drop",54)}<br>spring</td><td>${F.icon("palm",54)}<br>palm grove</td></tr>
     <tr><th>middle</th><td>${F.icon("tree",54)}<br>forest</td><td>${F.icon("tent",54)}<br>camp</td><td>${F.icon("bridge",54)}<br>rope bridge</td></tr>
     <tr><th>south</th><td>${F.icon("wave",54)}<br>beach</td><td>${F.icon("anchor",54)}<br>dock</td><td>${F.icon("cabin",54)}<br>store hut</td></tr></table>
     <table class="bigTable"><tr><th>Place</th><th>Steps from camp</th></tr>
     <tr><td>spring</td><td>300</td></tr><tr><td>dock</td><td>450</td></tr><tr><td>rope bridge</td><td>200</td></tr><tr><td>ridge</td><td>700</td></tr></table>`,qs:["What is directly north of the camp?","Which direction do you walk to get from the camp to the store hut? Name both directions you need.","Name one physical feature on this map and one thing people built.","Which place in the table is farthest from camp? If you drew a bar graph of the table, which bar would be tallest?"],key:["the spring (HSS-3.1)","south and east, in either order. The store hut sits in the south row and the east column. Partial: one of the two directions is approaching. (HSS-3.1)","Physical: the ridge, the spring, the forest, the beach, the palm grove. Human-made: the camp, the rope bridge, the dock, the store hut. One of each is what is being checked. Partial: one of the two kinds named is approaching. (HSS-3.1)","the ridge, 700 steps, and its bar would be the tallest. Partial: the farthest place named with no answer about the bar is approaching. (HSS-3.1)"]}]},{id:26,title:"Long Ago in This Place",short:"Long Ago",parts:[{title:"The First Nations Here",std:["HSS-3.2"],n:3,dur:90,dir:"Answer out loud. Use what is on the screen and what you have learned.",desc:"describing how the American Indian nations of California used the land long ago and how a nation is part of the state today",html:()=>`<p class="big">Oak trees grow across much of California. Many nations have their homelands here. In the fall they gathered acorns. They dried them. They ground them into flour. Then they rinsed the flour with water. They did that before cooking it. The harvest was more than work. Nations held a ceremony at the start of it. There was dancing and singing to give thanks. Their religious beliefs tied them to the land. That land fed them. Many nations still hold a gathering at acorn time today.</p>
     <div class="figure">${F.icon("acorn",88)}${F.icon("tree",88)}</div>`,qs:["The screen names four things nations did with acorns before cooking them. Name all four, in order.","Nations here held a ceremony of thanks before the acorn harvest began. What does that tell you about what the people believed about the land?","Are these nations only part of the past? Give one way a nation is part of California today."],key:["Gathered the acorns in the fall. Dried them. Ground them into flour. Rinsed the flour with water. All four, in that order. Partial: three of the four steps named, or all four out of order, is approaching. (HSS-3.2)","That the land was not only a food supply to them. Their religious beliefs tied them to it, so the harvest was treated as something to give thanks for and not only a job to get done. Accept any answer that names a belief about the land, not only the word ceremony. Partial: retelling the ceremony with no belief about the land named is approaching. (HSS-3.2)","No. Any true present-day answer: nations have their own tribal governments, they hold cultural events, people teach and learn the languages, nations care for land and water, members live and work in towns and cities across the state. Partial: saying no with no present-day example is approaching. (HSS-3.2)","Not scored, ask it anyway: which American Indian nation or nations have their homeland where this student lives? The answer is different for every family, so there is no key for it and it stays out of the rating. Tell the student the name if they do not know it, write it on the record sheet, and make it something to teach before the next check."]},{title:"A Town Over Time",std:["HSS-3.3"],n:3,dur:90,dir:"Look at the timeline. Answer out loud.",desc:"sequencing local historical events and describing the mark each period left on the land",html:()=>`<p class="big">A timeline for the town of Harbor Bend.</p>
     <table class="bigTable"><tr><th>Year</th><th>What happened</th></tr>
     <tr><td>1850</td><td>a trading post opens where the river meets the sea</td></tr>
     <tr><td>1878</td><td>a sawmill is built, and the forest on the hill is cut for lumber</td></tr>
     <tr><td>1915</td><td>a rail line reaches town, and orchards are planted on the flat land</td></tr>
     <tr><td>1960</td><td>a highway is built that goes around the town instead of through it</td></tr>
     <tr><td>2005</td><td>the old sawmill site becomes a park</td></tr></table>`,qs:["Put these three in order, earliest first: the park, the sawmill, the rail line.","Which event changed the hill. What did it do to it?","Pick one period on this timeline. What mark has it left on the land? Tell me one someone could still see today."],key:["sawmill, rail line, park. Partial: two of the three in the right order is approaching. (HSS-3.3)","the sawmill in 1878, which cut the forest off the hill for lumber. Partial: naming the sawmill with no account of what it did to the hill is approaching. (HSS-3.3)","Any period with a physical mark named: the trading post set the town where the river meets the sea, the bare or regrown hill, orchards on the flat land, the rail line’s route through town, a quiet main street after the highway went around, a park where the mill stood. Partial: naming a period with no mark on the land named is approaching. (HSS-3.3)"]}]},{id:27,title:"Rules and Work",short:"Rules",parts:[{title:"Rules, Laws and Government",std:["HSS-3.4"],n:4,dur:105,dir:"Answer out loud.",desc:"telling rules from laws and naming the basic parts and levels of United States government",html:()=>`<p class="big">On the ship there are rules. In a town there are laws.</p>
      <p class="big">The country keeps two documents under glass in Washington. The Declaration of Independence, signed in 1776, said the colonies would govern themselves. The Constitution, written in 1787, set up the three parts of the government, and it is still the highest law in the country.</p>
     <div class="figure">${F.icon("flag",88)}${F.icon("books",88)}</div>`,qs:["What is the difference between a rule in your own house and a law?","The United States government has three parts. One makes the laws, one carries them out, and one decides what the laws mean. Which part makes the laws?","Which part carries out the laws for the whole country. Who leads it?","Name the document that said the colonies would govern themselves. Then name another document. It set up three parts of government. It is still the highest law."],key:["A rule is set by a family, a class or a crew and applies in that place. A law is made by a government, applies to everyone there, and the government decides what happens when it is broken. Partial: describing a house rule with nothing said about who makes a law is approaching. (HSS-3.4)","Congress, the lawmaking part, also called the legislative branch. (HSS-3.4)","the executive branch, led by the President. Partial: one of the branch and the President named is approaching. (HSS-3.4)","the Declaration of Independence, signed in 1776, and the Constitution, written in 1787. The two names are what is being checked; the years are a bonus. Partial: one of the two documents named is approaching. (HSS-3.4)"]},{title:"Choices and the Local Economy",std:["HSS-3.5"],n:4,dur:105,dir:"Look at the price list. Answer out loud.",desc:"basic economic reasoning about scarce money, trade-offs, goods and services",html:()=>`<p class="big">The store hut on the island sells supplies and it also sharpens tools for a fee. The crew has 8 coins.</p>
     <table class="bigTable"><tr><th>Item</th><th>Price</th></tr>
     <tr><td>rope</td><td>4 coins</td></tr><tr><td>lantern</td><td>7 coins</td></tr>
     <tr><td>dried fruit</td><td>2 coins</td></tr></table>
     <div class="figure">${F.icon("coin",72)}${F.icon("lantern",72)}</div>`,qs:["Can the crew buy both the lantern and the rope with 8 coins? What do they give up if they buy the lantern?","You pick one thing over another. There is a name for what you give up. Explain that idea in your own words.","The hut sells rope and it sharpens tools. Which of those is a good and which is a service?","Name one job in your own town. Then say whether that worker makes a good or provides a service."],key:["No. The lantern and the rope together cost 11 coins and they have 8. Buying the lantern leaves 1 coin, so they give up the rope and the dried fruit as well. Partial: saying no with nothing named that the crew gives up is approaching. (HSS-3.5)","The idea of a trade-off, or opportunity cost: choosing one thing means doing without another, because money and goods are limited. The idea matters more than the term at this grade. Partial: naming the term with no explanation in the student's own words is approaching. (HSS-3.5)","Rope is a good, something you can hold. Sharpening a tool is a service, work someone does for you. Partial: one of the two sorted right is approaching. (HSS-3.5)","Any real local job sorted correctly: a baker makes a good, a dentist provides a service, a farmer produces a good, a bus driver provides a service. Partial: a real job named with the good or service label wrong is approaching. (HSS-3.5)"]}]}];const WC=FABLE.split(/\s+/).filter(Boolean).length;const readPart=STOPS[1].parts[0];readPart.n=WC;readPart.key[0]=readPart.key[0].replace("__WC__",WC);readPart.desc=`a ${WC}-word grade-level story read aloud`;const LEVELUPS={3:{id:"L3",title:"Level Up: Details and Examples",std:["RL.4.1"],needs:["RL.3.1"],n:1,dir:"Answer out loud. Use the story.",html:()=>`<p class="big">What kind of brother is ${BRO}? Give two details or examples from the story.</p><p class="passage sm">${FABLE}</p>`,key:["Kind, supportive, or encouraging, backed by 2 details: he told her it would be a piece of cake, sat in the front row, waved both arms so she could find him. (RL.4.1, inference with details)"]},10:{id:"L10",title:"Level Up: Bigger Rounding",std:["4.NBT.A.3"],needs:["3.NBT.A.1"],n:2,dir:"Say each answer out loud.",html:()=>`<p class="huge" style="font-size:clamp(3rem,10vw,6rem)">46,372</p><ol class="qlist"><li>Round to the nearest thousand.</li><li>Round to the nearest hundred.</li></ol>`,key:["46,000 (4.NBT.A.3)","46,400 (4.NBT.A.3)"]},12:{id:"L12",title:"Level Up: Missing Side",std:["4.MD.A.3"],needs:["3.MD.C.7"],n:1,dir:"Solve on your paper or in your head. Tell your teacher the answer.",html:()=>`<p class="big">A rectangle has an area of 48 square feet. It is 6 feet long. How wide is it?</p>`,key:["8 feet, from 48 ÷ 6 or 6 × ? = 48 (4.MD.A.3)"]},14:{id:"L14",title:"Level Up: Different Parts",std:["4.NF.A.2"],needs:["3.NF.A.3"],n:1,dir:"Show your thinking on your paper and hold it up.",html:()=>`<p class="big">Which is greater: 2/3 or 3/5? Show how you know.</p>`,key:["2/3. Shows 10/15 and 9/15, or compares each to 1/2 or with a drawing of same-size wholes. (4.NF.A.2)"]}};const PASSAGE_STD=["RL.3.1","RL.3.4","RI.3.1","RI.3.9","RL.4.1","W.3.8"];const MULT_N=10,FRAC_DENS=[1,2,3,4,6,8];const PV_COLS={ints:["Ten<br>thousands","Thousands","Hundreds","Tens","Ones"],decs:[]};let multSel=[0,0],pvVal="",fracOn={};function multHtml(){let h=`<div class="tool-scroll"><table class="mult"><tr><th>×</th>`;for(let c=1;c<=MULT_N;c++)h+=`<th data-r="0" data-c="${c}" class="${multSel[1]===c?"hl":""}">${c}</th>`;h+="</tr>";for(let r=1;r<=MULT_N;r++){h+=`<tr><th data-r="${r}" data-c="0" class="${multSel[0]===r?"hl":""}">${r}</th>`;for(let c=1;c<=MULT_N;c++){const hr=multSel[0]===r,hc=multSel[1]===c;h+=`<td data-r="${r}" data-c="${c}" class="${hr&&hc?"pick":hr||hc?"hl":""}">${r*c}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to light up its row and column. Click it again to clear.</p>`}function pvTable(){const cols=PV_COLS,raw=pvVal.replace(/[^0-9.]/g,""),bits=raw.split("."),ip=bits[0]||"",dp=bits[1]||"";let h="<tr>";cols.ints.forEach(c=>h+=`<th>${c}</th>`);if(cols.decs.length){h+=`<th class="pt"></th>`;cols.decs.forEach(c=>h+=`<th>${c}</th>`)}h+="</tr><tr>";cols.ints.forEach((c,i)=>{const k=ip.length-(cols.ints.length-i);h+=`<td>${k>=0?ip[k]:""}</td>`});if(cols.decs.length){h+=`<td class="pt">.</td>`;cols.decs.forEach((c,i)=>h+=`<td>${dp[i]||""}</td>`)}return h+"</tr>"}function pvHtml(){return`<label class="pv-in">Type a number<input type="text" inputmode="decimal" id="pvInput" value="${pvVal}" autocomplete="off"></label><div class="tool-scroll"><table class="pv" id="pvTable">${pvTable()}</table></div>`}function fracHtml(){return FRAC_DENS.map(d=>{const on=fracOn[d]||0;let r=`<div class="fs-row">`;for(let k=0;k<d;k++)r+=`<button class="fs-part${d>=10?" sm":""}${k<on?" on":""}" data-d="${d}" data-k="${k}">${d===1?"1 whole":"1/"+d}</button>`;return r+"</div>"}).join("")+`<p class="small">Click a piece to shade up to it. Click the last shaded piece to clear the row.</p>`}function starters(st){if(st.std.includes("W.3.3"))return["One time I felt nervous when ____.","First, ____.","Then, ____.","After that, ____.","In the end, ____."];if(st.std.includes("W.3.2"))return["Sea otters stay warm by ____.","One fact is ____.","Also, ____.","Another fact is ____.","Now you know ____."];return["I think ____ because ____.","One reason is ____.","For example, ____.","That is why ____."]}function sentHtml(st){return`<ul class="starters">${starters(st).map(x=>`<li>${x}</li>`).join("")}</ul>`}const TOOLS={mult:{name:"Multiplication chart",std:["3.OA.A.1","3.OA.A.2","3.OA.D.8","3.MD.C.7","4.MD.A.3"],html:multHtml,bind:(b,r)=>b.querySelectorAll("[data-r]").forEach(c=>c.onclick=()=>{const row=+c.dataset.r,k=+c.dataset.c;multSel=multSel[0]===row&&multSel[1]===k?[0,0]:[row,k];r()})},pv:{name:"Place value chart",std:["3.NBT.A.1","4.NBT.A.3"],html:pvHtml,bind:b=>{const inp=b.querySelector("#pvInput"),tb=b.querySelector("#pvTable");if(inp&&tb)inp.oninput=()=>{pvVal=inp.value.replace(/[^0-9.,]/g,"");tb.innerHTML=pvTable()}}},frac:{name:"Fraction strips",std:["3.NF.A.2","3.NF.A.3"],html:fracHtml,bind:(b,r)=>b.querySelectorAll(".fs-part").forEach(x=>x.onclick=()=>{const d=+x.dataset.d,k=+x.dataset.k;fracOn[d]=fracOn[d]===k+1?0:k+1;r()})},sent:{name:"Sentence starters",std:["W.3.1","W.3.2","W.3.3"],html:sentHtml}};const SUP_CAVEATS=[{t:"frac",msg:"Fraction strips can show the answer to the equal fractions and comparing questions. Rate on whether the student can explain what the strips show."},{t:"sent",msg:"Sentence starters supply the linking or time words and the closing, so count those checks as supported, not independent."},{t:"passage",std:["RL.3.1","RL.3.4","RI.3.1","RI.3.9","RL.4.1"],msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
